SELECT shipped_cohort, cost_count, stddev_cost FROM (SELECT CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END AS shipped_cohort, COUNT(cost) AS cost_count, ROUND(STDDEV(cost), 2) AS stddev_cost FROM shipments GROUP BY CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END) AS x WHERE stddev_cost >= 55 ORDER BY shipped_cohort
